import { z } from "zod";

/** The contact form ("Start a run"), validated on the server; the client mirrors the limits. */
export const ContactSchema = z.object({
  task: z.string().trim().min(10, "Tell me a bit more — at least a sentence.").max(2000),
  where: z.string().trim().max(500).default(""),
  email: z.string().trim().email("That email doesn't look right."),
  /** honeypot: real people never see or fill it */
  company: z.string().max(0).optional().or(z.literal("")),
  /** the system generated by the prompt (C2), as JSON */
  system: z.string().max(4000).optional(),
});

export type ContactInput = z.infer<typeof ContactSchema>;
